insert into customer_types (slug, name, description, sort_order) values
  ('smb', 'Small Business', 'Roughly 1–50 employees. Short cycles, owner is usually the buyer.', 0),
  ('mid-market', 'Mid-Market', 'Roughly 51–1,000 employees. Committee buying, defined procurement.', 10),
  ('enterprise', 'Enterprise', '1,000+ employees. Long cycles, multiple stakeholders, formal RFPs.', 20),
  ('government', 'Government & Public Sector', 'Federal, state, provincial and municipal. Procurement rules apply.', 30),
  ('healthcare-providers', 'Healthcare Providers & Systems', 'Hospitals, clinics, practices and integrated delivery networks.', 40),
  ('education', 'Education & Academic', 'Schools, districts, colleges and universities.', 50),
  ('channel-partners', 'Channel, Reseller & Distributor', 'Selling through partners rather than direct to the end user.', 60),
  ('consumer', 'Consumer (B2C)', 'Selling directly to individuals.', 70);
insert into sales_models (slug, name, description, sort_order) values
  ('inside-sales', 'Inside Sales', 'Sold remotely by phone, email and video. No routine travel.', 0),
  ('field-sales', 'Field / Outside Sales', 'In-person selling, territory travel, on-site meetings.', 10),
  ('outbound-hunting', 'Outbound / Hunting', 'Self-generated pipeline through cold outreach and prospecting.', 20),
  ('inbound-closing', 'Inbound / Closing', 'Working leads generated by marketing rather than sourcing them.', 30),
  ('account-management', 'Account Management / Farming', 'Growing and retaining existing accounts rather than winning new ones.', 40),
  ('channel-sales', 'Channel & Partner Sales', 'Recruiting and enabling resellers, distributors and partners.', 50),
  ('business-development', 'Business Development & Partnerships', 'Strategic alliances, referral networks and new market entry.', 60),
  ('solution-selling', 'Solution & Technical Selling', 'Consultative, technically involved sales with proof-of-concept work.', 70);
insert into compensation_types (slug, name, description, has_guaranteed_pay, sort_order) values
  ('commission-only', 'Commission Only', 'Paid purely on results. No guaranteed income.', false, 0),
  ('base-plus-commission', 'Base + Commission', 'A guaranteed base salary plus performance commission.', true, 10),
  ('draw-against-commission', 'Draw Against Commission', 'Regular advance payments offset against future commission. Provides cash flow while a pipeline builds.', true, 20),
  ('retainer', 'Retainer', 'A fixed recurring fee for an agreed scope of work.', true, 30),
  ('retainer-plus-commission', 'Retainer + Commission', 'A fixed recurring fee plus upside on results. Common for fractional roles.', true, 40),
  ('fractional', 'Fractional (Fixed Monthly)', 'A defined number of hours or days per month at a fixed rate.', true, 50),
  ('contract-project', 'Contract / Project Fee', 'A fixed fee for a defined project or engagement period.', true, 60);
